import re
from auto_config.generator.vcu.managed_objects.managed_object import ManagedObject


class EthlkParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):

        self.set_parameter('administrativeState', 'unlocked')
        self.set_underLyingInterface()

    def set_underLyingInterface(self):
        srch = re.search(r"TNL-(\d+)/", self.dist_name)
        tnl_num = srch.group(1)
        if tnl_num == '1' or tnl_num == '4':
            self.set_parameter('underLyingInterface', 'oam')
        elif tnl_num == '2' or tnl_num == '5':
            self.set_parameter('underLyingInterface', 'extc')
        elif tnl_num == '3' or tnl_num == '6':
            self.set_parameter('underLyingInterface', 'extu')
